mkitem!{mkstruct!{# [doc = " `Exclusive` provides only _mutable_ access, also referred to as _exclusive_"] # [doc = " access to the underlying value. It provides no _immutable_, or _shared_"] # [doc = " access to the underlying value."] # [doc = ""] # [doc = " While this may seem not very useful, it allows `Exclusive` to _unconditionally_"] # [doc = " implement [`Sync`]. Indeed, the safety requirements of `Sync` state that for `Exclusive`"] # [doc = " to be `Sync`, it must be sound to _share_ across threads, that is, it must be sound"] # [doc = " for `&Exclusive` to cross thread boundaries. By design, a `&Exclusive` has no API"] # [doc = " whatsoever, making it useless, thus harmless, thus memory safe."] # [doc = ""] # [doc = " Certain constructs like [`Future`]s can only be used with _exclusive_ access,"] # [doc = " and are often `Send` but not `Sync`, so `Exclusive` can be used as hint to the"] # [doc = " Rust compiler that something is `Sync` in practice."] # [doc = ""] # [doc = " ## Examples"] # [doc = " Using a non-`Sync` future prevents the wrapping struct from being `Sync`"] # [doc = " ```compile_fail"] # [doc = " use core::cell::Cell;"] # [doc = ""] # [doc = " async fn other() {}"] # [doc = " fn assert_sync<T: Sync>(t: T) {}"] # [doc = " struct State<F> {"] # [doc = "     future: F"] # [doc = " }"] # [doc = ""] # [doc = " assert_sync(State {"] # [doc = "     future: async {"] # [doc = "         let cell = Cell::new(1);"] # [doc = "         let cell_ref = &cell;"] # [doc = "         other().await;"] # [doc = "         let value = cell_ref.get();"] # [doc = "     }"] # [doc = " });"] # [doc = " ```"] # [doc = ""] # [doc = " `Exclusive` ensures the struct is `Sync` without stripping the future of its"] # [doc = " functionality."] # [doc = " ```"] # [doc = " #![feature(exclusive_wrapper)]"] # [doc = " use core::cell::Cell;"] # [doc = " use core::sync::Exclusive;"] # [doc = ""] # [doc = " async fn other() {}"] # [doc = " fn assert_sync<T: Sync>(t: T) {}"] # [doc = " struct State<F> {"] # [doc = "     future: Exclusive<F>"] # [doc = " }"] # [doc = ""] # [doc = " assert_sync(State {"] # [doc = "     future: Exclusive::new(async {"] # [doc = "         let cell = Cell::new(1);"] # [doc = "         let cell_ref = &cell;"] # [doc = "         other().await;"] # [doc = "         let value = cell_ref.get();"] # [doc = "     })"] # [doc = " });"] # [doc = " ```"] # [doc = ""] # [doc = " ## Parallels with a mutex"] # [doc = " In some sense, `Exclusive` can be thought of as a _compile-time_ version of"] # [doc = " a mutex, as the borrow-checker guarantees that only one `&mut` can exist"] # [doc = " for any value. This is a parallel with the fact that"] # [doc = " `&` and `&mut` references together can be thought of as a _compile-time_"] # [doc = " version of a read-write lock."] # [unstable (feature = "exclusive_wrapper" , issue = "98407")] # [doc (alias = "SyncWrapper")] # [doc (alias = "SyncCell")] # [doc (alias = "Unique")] # [derive (Default)] # [repr (transparent)] pub struct Exclusive < T : ? Sized > { inner : T , }}}
