mkitem!{mkimpl!{impl < T : ? Sized > Exclusive < T > { # [doc = " Gets exclusive access to the underlying value."] # [unstable (feature = "exclusive_wrapper" , issue = "98407")] # [must_use] # [inline] pub const fn get_mut (& mut self) -> & mut T { & mut self . inner } # [doc = " Gets pinned exclusive access to the underlying value."] # [doc = ""] # [doc = " `Exclusive` is considered to _structurally pin_ the underlying"] # [doc = " value, which means _unpinned_ `Exclusive`s can produce _unpinned_"] # [doc = " access to the underlying value, but _pinned_ `Exclusive`s only"] # [doc = " produce _pinned_ access to the underlying value."] # [unstable (feature = "exclusive_wrapper" , issue = "98407")] # [must_use] # [inline] pub const fn get_pin_mut (self : Pin < & mut Self >) -> Pin < & mut T > { unsafe { Pin :: new_unchecked (& mut self . get_unchecked_mut () . inner) } } # [doc = " Build a _mutable_ reference to an `Exclusive<T>` from"] # [doc = " a _mutable_ reference to a `T`. This allows you to skip"] # [doc = " building an `Exclusive` with [`Exclusive::new`]."] # [unstable (feature = "exclusive_wrapper" , issue = "98407")] # [must_use] # [inline] pub const fn from_mut (r : & '_ mut T) -> & '_ mut Exclusive < T > { unsafe { & mut * (r as * mut T as * mut Exclusive < T >) } } # [doc = " Build a _pinned mutable_ reference to an `Exclusive<T>` from"] # [doc = " a _pinned mutable_ reference to a `T`. This allows you to skip"] # [doc = " building an `Exclusive` with [`Exclusive::new`]."] # [unstable (feature = "exclusive_wrapper" , issue = "98407")] # [must_use] # [inline] pub const fn from_pin_mut (r : Pin < & '_ mut T >) -> Pin < & '_ mut Exclusive < T > > { unsafe { Pin :: new_unchecked (Self :: from_mut (r . get_unchecked_mut ())) } } }}}
